mapper.select:

SELECT <include refid="Base_Column_List" />
FROM file_system
WHERE file_system_size > #{minSize}
ORDER BY file_system_size DESC


    LIMIT #{limit}


SELECT <include refid="Base_Column_List" />
FROM file_system
WHERE create_time >= #{startTime}
ORDER BY create_time DESC


    LIMIT #{limit}

mapper.delete:

DELETE FROM file_system
WHERE file_system_status IN (0, 1)
AND TIMESTAMPDIFF(HOUR, create_time, NOW()) > #{hours}

mapper.select:
SELECT 
FROM file_system


        create_time >= #{startTime}


        AND create_time <= #{endTime}


        AND file_system_status = #{status}


ORDER BY create_time DESC

    LIMIT #{limit}

SELECT 
FROM file_system


        (file_system_name LIKE CONCAT('%', #{keyword}, '%')
        OR file_system_original_name LIKE CONCAT('%', #{keyword}, '%'))


        AND file_system_type = #{fileType}


        AND file_system_status = #{status}


        AND file_system_size >= #{minSize}


        AND file_system_size <= #{maxSize}


ORDER BY 


        ${orderBy}


        create_time DESC



    LIMIT #{offset}, #{limit}
